## Minimal Archetype-Based Entity Component System (GDScript for Godot 4.3)
## A RefCounted class managing entities as handles (int: slot + generation) and archetypes.

# --- Internal Data Structures ---
# - entity_data: Dictionary[slot, generation]
# - free_slots: Array[int]
# - archetype_map: Dictionary[archetype_key, archetype_entities]
# - entity_archetype: Dictionary[entity, archetype_key]
# - entity_components: Dictionary[entity, Dictionary]

var _generations: Array = []        # Index = slot, value = generation
var _free_slots: Array = []         # Pool of recycled slot indices

# Maps a sorted signature (as a String-sorted PackedStringArray or PoolArray equivalent)
# to a Dictionary[entity: int, Dictionary].
var _archetypes: Dictionary = {}    # Dictionary[String, Dictionary]

# Track each alive entity's current archetype signature.
var _entity_archetype: Dictionary = {}  # Dictionary[int, String]

# Helper for archetype signature representation.
const empty_archetype_sig: String = ""  # Special key for 0 components

# ENTITY HANDLE MANAGEMENT
# A handle is packed into an int: bits 31-28 generation, bits 27-0 slot (max 268M entities).
# Actually, to fit within signed 32-bit int (Godot's int is 64-bit), let's use bit shifting.
# Let's pack: lower 24 bits = slot, upper 40 bits = generation. Safe in 64-bit int.
const slot_bits: int = 24
const slot_mask: int = (1 << slot_bits) - 1


func get_index(entity: int) -> int:
    return entity & slot_mask


func get_generation(entity: int) -> int:
    return entity >> slot_bits


func _make_handle(slot: int, generation: int) -> int:
    return (generation << slot_bits) | slot


func _is_slot_in_use(slot: int) -> bool:
    if slot < 0 or slot >= _generations.size():
        return false
    # Slot is in use if it's not in the free pool.
    return _free_slots.bsearch(slot) == -1


func is_alive(entity: int) -> bool:
    var slot = get_index(entity)
    var gen = get_generation(entity)
    if slot < 0 or slot >= _generations.size():
        return false
    return _generations[slot] == gen


func _ensure_slot(slot: int):
    while _generations.size() <= slot:
        _generations.append(0)


func create_entity() -> int:
    var slot: int
    var gen: int
    if _free_slots.size() > 0:
        slot = _free_slots.pop_back()
        gen = _generations[slot] + 1
    else:
        slot = _generations.size()
        gen = 1
        _ensure_slot(slot)
    _generations[slot] = gen

    var entity = _make_handle(slot, gen)

    # Register as the empty archetype
    var sig = empty_archetype_sig
    if not _archetypes.has(sig):
        _archetypes[sig] = {}
    _archetypes[sig][entity] = {}
    _entity_archetype[entity] = sig

    return entity


func destroy_entity(entity: int) -> bool:
    if not is_alive(entity):
        return false

    # Clean up archetypes/data
    var sig = _entity_archetype[entity]
    _archetypes[sig].erase(entity)
    if _archetypes[sig].is_empty():
        _archetypes.erase(sig)
    _entity_archetype.erase(entity)

    # Release slot
    var slot = get_index(entity)
    _free_slots.append(slot)
    _free_slots.sort()

    return true


# ARCHETYPE SIGNATURE HELPERS
func _get_sig_from_dict(d: Dictionary) -> String:
    var keys = d.keys()
    keys.sort()
    return ",".join(PackedStringArray(keys))


func _get_sig_from_array(a: Array) -> String:
    var sorted = a.duplicate()
    sorted.sort()
    return ",".join(PackedStringArray(sorted))


func _get_comps_from_sig(sig: String) -> Array:
    if sig == empty_archetype_sig:
        return []
    return Array(sig.split(","))


func get_component_types(entity: int) -> Variant:
    if not is_alive(entity):
        return null
    return _get_comps_from_sig(_entity_archetype[entity])


func _migrate(entity: int, sig: String, components: Dictionary):
    var old_sig = _entity_archetype[entity]
    _archetypes[old_sig].erase(entity)
    if _archetypes[old_sig].is_empty():
        _archetypes.erase(old_sig)

    if not _archetypes.has(sig):
        _archetypes[sig] = {}
    _archetypes[sig][entity] = components
    _entity_archetype[entity] = sig


func add_component(entity: int, component_type: StringName, data: Dictionary) -> bool:
    if not is_alive(entity):
        return false

    var sig = _entity_archetype[entity]
    var components = _archetypes[sig][entity]

    if components.has(component_type):
        components[component_type] = data
        return true

    # New component -> migrate
    var new_comps = components.duplicate()
    new_comps[component_type] = data
    var new_sig = _get_sig_from_dict(new_comps)
    _migrate(entity, new_sig, new_comps)
    return true


func remove_component(entity: int, component_type: StringName) -> bool:
    if not is_alive(entity):
        return false

    var sig = _entity_archetype[entity]
    var components = _archetypes[sig][entity]
    if not components.has(component_type):
        return false

    var new_comps = components.duplicate()
    new_comps.erase(component_type)
    var new_sig = _get_sig_from_dict(new_comps)
    _migrate(entity, new_sig, new_comps)
    return true


func has_component(entity: int, component_type: StringName) -> bool:
    if not is_alive(entity):
        return false
    var sig = _entity_archetype[entity]
    return _archetypes[sig][entity].has(component_type)


func get_component(entity: int, component_type: StringName) -> Variant:
    if not is_alive(entity):
        return null
    var sig = _entity_archetype[entity]
    var components = _archetypes[sig][entity]
    return components.get(component_type)


func _is_superset(sup_sig: String, req_array: Array) -> bool:
    var sup = _get_comps_from_sig(sup_sig)
    for r in req_array:
        if not sup.has(r):
            return false
    return true


func query(required_types: Array) -> Array:
    var req_set = {}
    for t in required_types:
        req_set[t] = true
    var unique_req = req_set.keys()

    var results = []
    for sig in _archetypes:
        if _is_superset(sig, unique_req):
            for entity in _archetypes[sig]:
                results.append(entity)
    results.sort_custom(func(a, b): return get_index(a) < get_index(b))
    return results


func get_entities_with_exact_types(types: Array) -> Array:
    var target_sig = _get_sig_from_array(types)
    var results = []
    if _archetypes.has(target_sig):
        for entity in _archetypes[target_sig]:
            results.append(entity)
    results.sort_custom(func(a, b): return get_index(a) < get_index(b))
    return results

