    _archetypes[sig].erase(entity)
    if _archetypes[sig].is_empty():
        _archetypes.erase(sig)
    _entity_archetype.erase(entity)

    # Release slot
    var slot = get_index(entity)
    _free_slots.append(slot)
    _free_slots.sort()

    return true


# ARCHETYPE SIGNATURE HELPERS
func _get_sig_from_dict(d: Dictionary) -> String:
    var keys = d.keys()
    keys.sort()
    return ",".join(PackedStringArray(keys))


func _get_sig_from_array(a: Array) -> String:
    var sorted = a.duplicate()
    sorted.sort()
    return ",".join(PackedStringArray(sorted))


func _get_comps_from_sig(sig: String) -> Array:
    if sig == empty_archetype_sig:
        return []
    return Array(sig.split(","))


func get_component_types(entity: int) -> Variant:
    if not is_alive(entity):
        return null
    return _get_comps_from_sig(_entity_archetype.get(entity, empty_archetype_sig))


func _migrate(entity: int, sig: String, components: Dictionary):
    var old_sig = _entity_archetype[entity]
    _archetypes[old_sig].erase(entity)
    if _archetypes[old_sig].is_empty():
        _archetypes.erase(old_sig)

    if not _archetypes.has(sig):
        _archetypes[sig] = {}
    _archetypes[sig][entity] = components
    _entity_archetype[entity] = sig


func add_component(entity: int, component_type: StringName, data: Dictionary) -> bool:
    if not is_alive(entity):
        return false

    var sig = _entity_archetype[entity]
    var components = _archetypes[sig][entity]

    if components.has(component_type):
        components[component_type] = data
        return true

    # New component -> migrate
    var new_comps = components.duplicate()
    new_comps[component_type] = data
    var new_sig = _get_sig_from_dict(new_comps)
    _migrate(entity, new_sig, new_comps)
    return true


func remove_component(entity: int, component_type: StringName) -> bool:
    if not is_alive(entity):
        return false

    var sig = _entity_archetype[entity]
    var components = _archetypes[sig][entity]
    if not components.has(component_type):
        return false

    var new_comps = components.duplicate()
    new_comps.erase(component_type)
    var new_sig = _get_sig_from_dict(new_comps)
    _migrate(entity, new_sig, new_comps)
    return true


func has_component(entity: int, component_type: StringName) -> bool:
    if not is_alive(entity):
        return false
    var sig = _entity_archetype[entity]
    return _archetypes[sig][entity].has(component_type)


func get_component(entity: int, component_type: StringName) -> Variant:
    if not is_alive(entity):
        return null
    var sig = _entity_archetype[entity]
    var components = _archetypes[sig][entity]
    return components.get(component_type)


func _is_superset(sup_sig: String, req_array: Array) -> bool:
    var sup = _get_comps_from_sig(sup_sig)
    for r in req_array:
        if not sup.has(r):
            return false
    return true


func query(required_types: Array) -> Array:
    var req_set = {}
    for t in required_types:
        req_set[t] = true
    var unique_req = req_set.keys()

    var results = []
    for sig in _archetypes:
        if _is_superset(sig, unique_req):
            for entity in _archetypes[sig]:
                results.append(entity)
    results.sort_custom(func(a, b): return get_index(a) < get_index(b))
    return results


func get_entities_with_exact_types(types: Array) -> Array:
    var target_sig = _get_sig_from_array(types)
    var results = []
    if _archetypes.has(target_sig):
        for entity in _archetypes[target_sig]:
            results.append(entity)
    results.sort_custom(func(a, b): return get_index(a) < get_index(b))
    return results
